<?php require 'config.php';$pageTitle='Đăng ký';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8)$error='Nhập tên, email hợp lệ và mật khẩu ít nhất 8 ký tự.';else{try{$st=$pdo->prepare('INSERT INTO users(full_name,email,password,phone,address,role,created_at) VALUES(?,?,?,?,?,?,NOW())');$st->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone,'','customer']);header('Location: login.php?registered=1');exit;}catch(PDOException $e){$error='Email đã được sử dụng hoặc dữ liệu không hợp lệ.';}}}require 'includes/header.php';?><div class="row justify-content-center"><div class="col-md-6"><form method="post" class="content-card"><h1 class="section-title">Tạo tài khoản</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="mb-3"><label class="form-label">Họ tên</label><input class="form-control" name="full_name" required></div><div class="mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required></div><div class="mb-3"><label class="form-label">Số điện thoại</label><input class="form-control" name="phone"></div><div class="mb-3"><label class="form-label">Mật khẩu (ít nhất 8 ký tự)</label><input class="form-control" type="password" name="password" minlength="8" required></div><button class="btn btn-red">Đăng ký</button><p class="mt-3 mb-0">Đã có tài khoản? <a href="login.php">Đăng nhập</a></p></form></div></div><?php require 'includes/footer.php';?>
